import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { MessageService } from 'primeng/api';
import { SystemSettingsService } from '../../../../../../libs/openapi/src/api/system-settings.service';

@Component({
  selector: 'app-payment-info',
  templateUrl: './payment-info.component.html',
  styleUrls: ['./payment-info.component.scss'],
  providers: [MessageService],
})
export class PaymentInfoComponent implements OnInit {
  paymentInfoForm!: FormGroup;
  loading: boolean = false;
  lastUpdated: string = '';

  constructor(
    private fb: FormBuilder,
    private systemSettingsService: SystemSettingsService,
    private messageService: MessageService
  ) {}

  ngOnInit(): void {
    this.paymentInfoForm = this.fb.group({
      content: [''],
    });
    this.loadPaymentInfo();
  }

  loadPaymentInfo(): void {
    this.loading = true;
    this.systemSettingsService
      .apiAdminSystemSettingsTransferPaymentGet()
      .subscribe({
        next: (response) => {
          // Assuming the response has data.content and data.updatedAt properties
          if (response.data) {
            this.paymentInfoForm.patchValue({
              content: response.data.text,
            });
            // Format date if available
            if (response.data.updatedAt) {
              this.lastUpdated = new Date(
                response.data.updatedAt
              ).toLocaleString();
            }
          }
          this.loading = false;
        },
        error: (error) => {
          this.messageService.add({
            severity: 'error',
            summary: '錯誤',
            detail: '無法載入付款資訊',
          });
          this.loading = false;
        },
      });
  }

  savePaymentInfo(): void {
    if (this.paymentInfoForm.valid) {
      this.loading = true;
      const content = this.paymentInfoForm.get('content')?.value || '';

      this.systemSettingsService
        .apiAdminSystemSettingsTransferPaymentPut(content)
        .subscribe({
          next: (response) => {
            this.messageService.add({
              severity: 'success',
              summary: '成功',
              detail: '付款資訊已更新',
            });

            // Update the last updated time if available in response
            if (response.data && response.data.updatedAt) {
              this.lastUpdated = new Date(
                response.data.updatedAt
              ).toLocaleString();
            }

            this.loading = false;
          },
          error: (error) => {
            this.messageService.add({
              severity: 'error',
              summary: '錯誤',
              detail: '更新付款資訊失敗',
            });
            this.loading = false;
          },
        });
    }
  }
}
